ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), item_type=VALUES(item_type), slot=VALUES(slot), price=VALUES(price), payload_json=VALUES(payload_json), is_active=VALUES(is_active);

ON DUPLICATE KEY UPDATE title=VALUES(title), description=VALUES(description), icon=VALUES(icon), currency_reward=VALUES(currency_reward), condition_json=VALUES(condition_json), status=VALUES(status);
